package fr.proutlost.worldprep.job;
import java.util.EnumSet;
public final class WorldPrepJob {public enum State{QUEUED,ANALYZING,PREVIEWING,PREVIEW_READY,APPLYING,PAUSED,COMPLETED,CANCELLED,FAILED,ROLLING_BACK,ROLLED_BACK}private State state=State.QUEUED,pausedFrom;private long cursor;public State state(){return state;}public long cursor(){return cursor;}public void advance(long amount){if(amount<0||!(state==State.ANALYZING||state==State.PREVIEWING||state==State.APPLYING||state==State.ROLLING_BACK))throw new IllegalStateException();cursor=Math.addExact(cursor,amount);}public void transition(State to){if(!allowed(state,to))throw new IllegalStateException(state+" -> "+to);state=to;}public void pause(){if(!EnumSet.of(State.ANALYZING,State.PREVIEWING,State.APPLYING,State.ROLLING_BACK).contains(state))throw new IllegalStateException();pausedFrom=state;state=State.PAUSED;}public void resume(){if(state!=State.PAUSED||pausedFrom==null)throw new IllegalStateException();state=pausedFrom;pausedFrom=null;}private static boolean allowed(State a,State b){return switch(a){case QUEUED->b==State.ANALYZING||b==State.CANCELLED;case ANALYZING->b==State.PREVIEWING||b==State.FAILED||b==State.CANCELLED;case PREVIEWING->b==State.PREVIEW_READY||b==State.FAILED||b==State.CANCELLED;case PREVIEW_READY->b==State.APPLYING||b==State.CANCELLED;case APPLYING->b==State.COMPLETED||b==State.FAILED||b==State.ROLLING_BACK;case FAILED,COMPLETED->b==State.ROLLING_BACK;case ROLLING_BACK->b==State.ROLLED_BACK||b==State.FAILED;default->false;};}}
